import { useEffect, useState } from "react";

/*
 * A stand-in for a data request, so loading examples show the skeleton and then the reveal. In an
 * app the data comes from a route loader, TanStack Query or `use(promise)`; the UI only needs the
 * value and whether a request is in flight.
 */

/** How long the example "server" takes to answer, in milliseconds. */
const defaultLatency = 1600;

interface SimulatedFetchOptions {
  latency?: number;
  /** The request rejects instead of resolving. */
  fail?: boolean;
}

interface SimulatedFetch<T> {
  /** The loaded value; `undefined` until the first response. */
  data: T | undefined;
  /** A request is in flight, the first one or a refetch. */
  loading: boolean;
  error: Error | undefined;
  /** Drops the data and loads again, as on a first visit. */
  reload: () => void;
  /** Loads again while the current data stays on screen. */
  refetch: () => void;
}

const useSimulatedFetch = <T,>(
  value: T,
  { latency = defaultLatency, fail = false }: SimulatedFetchOptions = {},
): SimulatedFetch<T> => {
  const [request, setRequest] = useState({ id: 0 });

  // What the last response answered: the request and the value it was for. A new value (say, a new
  // page or sort order) is a new request, while the last response stays on screen.
  const [settled, setSettled] = useState<{
    id: number;
    value: T;
    data?: T;
    error?: Error;
  } | null>(null);

  useEffect(() => {
    const timer = setTimeout(() => {
      setSettled(
        fail
          ? { error: new Error("The server did not respond. Try again."), id: request.id, value }
          : { data: value, id: request.id, value },
      );
    }, latency);

    return () => {
      clearTimeout(timer);
    };
  }, [request, latency, fail, value]);

  const current = settled?.id === request.id && settled.value === value ? settled : null;
  // `reload` clears the last response, so only refetches keep data on screen.
  const previous = settled?.data;

  return {
    data: current === null ? previous : current.data,
    error: current?.error,
    loading: current === null,
    refetch: () => {
      setRequest((last) => ({ id: last.id + 1 }));
    },
    reload: () => {
      setSettled(null);
      setRequest((last) => ({ id: last.id + 1 }));
    },
  };
};

/** Playground controls shared by loading examples. */
const latencyArgType = {
  latency: { control: { max: 5000, min: 0, step: 100, type: "number" } },
} as const;

export { defaultLatency, latencyArgType, useSimulatedFetch };

export type { SimulatedFetch, SimulatedFetchOptions };

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { Avatar, AvatarFallback, AvatarImage } from "@/registry/erbium/ui/avatar";
import { Badge } from "@/registry/erbium/ui/badge";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/registry/erbium/ui/item";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { useSimulatedFetch } from "../../loading";
import { members, sampleMembers } from "../fixtures";
import type { Member } from "../fixtures";

export const SkeletonMemberList = ({ members: value }: { members: Member[] }) => (
  <ItemGroup>
    {value.map((member) => (
      <Item key={member.id} size="sm">
        <ItemMedia>
          <Avatar>
            <AvatarImage src={member.avatar} alt="" />
            <AvatarFallback>{member.name.charAt(0)}</AvatarFallback>
          </Avatar>
        </ItemMedia>
        <ItemContent>
          <ItemTitle>{member.name}</ItemTitle>
          <ItemDescription>{member.email}</ItemDescription>
        </ItemContent>
        <ItemActions>
          <Badge variant="outline">{member.role}</Badge>
        </ItemActions>
      </Item>
    ))}
  </ItemGroup>
);

/** Avatars are drawn as blocks in their own shape; each image keeps its block until it decodes. */
export const SkeletonAvatar = ({ latency }: { latency?: number }) => {
  const request = useSimulatedFetch(members, { latency });

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <Skeleton
        data={request.data}
        sample={sampleMembers}
        loading={request.loading}
        id="skeleton-members"
        label="Loading members"
        className="w-full"
      >
        {(value) => <SkeletonMemberList members={value} />}
      </Skeleton>
    </div>
  );
};

import { Skeleton } from "@/registry/erbium/ui/skeleton";

/**
 * Without content, `Skeleton` is a box you size yourself. Use it only when there is nothing to
 * render a sample from, such as a chart whose shape depends on the data. It shares the page's
 * shimmer with every measured skeleton.
 */
export default function SkeletonBoxExample() {
  return (
    <div className="flex w-full max-w-sm flex-col gap-related">
      <Skeleton className="h-40 w-full rounded-xl" />
      <div className="flex gap-related">
        <Skeleton className="h-4 flex-1" />
        <Skeleton className="h-4 w-16" />
      </div>
    </div>
  );
}

import { Badge } from "@/registry/erbium/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { useSimulatedFetch } from "../../loading";
import { article, sampleArticle } from "../fixtures";
import type { Article } from "../fixtures";

const ArticleCard = ({ article: value }: { article: Article }) => (
  <Card className="w-full max-w-sm">
    <CardHeader>
      <div className="flex flex-wrap gap-1.5">
        {value.tags.map((tag) => (
          <Badge key={tag} variant="secondary">
            {tag}
          </Badge>
        ))}
      </div>
      <CardTitle>{value.title}</CardTitle>
      <CardDescription>{value.excerpt}</CardDescription>
    </CardHeader>
    <CardContent />
    <CardFooter className="justify-between text-caption text-muted-foreground">
      <span>{value.author}</span>
      <span>
        {value.date} · {value.readingTime}
      </span>
    </CardFooter>
  </Card>
);

/** Badges are drawn as pills, text as bars, and the card keeps its surface while it loads. */
export const defaultProps = {} satisfies { latency?: number };

export default function SkeletonCardExample({ latency }: { latency?: number } = defaultProps) {
  const request = useSimulatedFetch(article, { latency });

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <Skeleton
        data={request.data}
        sample={sampleArticle}
        loading={request.loading}
        id="skeleton-article"
        label="Loading article"
        className="w-full"
      >
        {(value) => <ArticleCard article={value} />}
      </Skeleton>
    </div>
  );
}

import { Avatar, AvatarFallback, AvatarImage } from "@/registry/erbium/ui/avatar";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { useSimulatedFetch } from "../../loading";
import { profile, sampleProfile } from "../fixtures";
import type { Profile } from "../fixtures";

const initials = (name: string) =>
  name
    .split(" ")
    .map((part) => part.charAt(0))
    .join("");

export const ProfileCard = ({ profile: value }: { profile: Profile }) => (
  <Card className="w-full max-w-sm">
    <CardHeader>
      <div className="flex items-center gap-group">
        <Avatar size="lg">
          <AvatarImage src={value.avatar} alt="" />
          <AvatarFallback>{initials(value.name)}</AvatarFallback>
        </Avatar>
        <div className="flex min-w-0 flex-col gap-0.5">
          <CardTitle>{value.name}</CardTitle>
          <CardDescription>
            {value.role} · {value.handle}
          </CardDescription>
        </div>
      </div>
    </CardHeader>
    <CardContent>
      <p className="text-body text-muted-foreground">{value.bio}</p>
    </CardContent>
  </Card>
);

/**
 * Render what you would show once the data arrives. Until then the card is drawn from
 * `sampleProfile`: a bar for each line of text and a block for the avatar, at their real size.
 */
const SkeletonDemo = ({ latency }: { latency?: number }) => {
  const request = useSimulatedFetch(profile, { latency });

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <Skeleton
        data={request.data}
        sample={sampleProfile}
        loading={request.loading}
        id="skeleton-profile"
        label="Loading profile"
        className="w-full"
      >
        {(value) => <ProfileCard profile={value} />}
      </Skeleton>
    </div>
  );
};

export default SkeletonDemo;

import { useId } from "react";
import { FieldGroup, FieldLabel } from "@/registry/erbium/ui/field";
import { Form, useAppForm } from "@/registry/erbium/ui/form";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/erbium/ui/select";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { useSimulatedFetch } from "../../loading";
import { preferences, samplePreferences } from "../fixtures";
import type { Preferences } from "../fixtures";

const languages = [
  { label: "English", value: "en" },
  { label: "Deutsch", value: "de" },
  { label: "فارسی", value: "fa" },
];

const PreferencesForm = ({ initial }: { initial: Preferences }) => {
  const languageId = useId();
  const form = useAppForm({ defaultValues: initial });

  return (
    <Form form={form} className="w-full">
      <FieldGroup>
        <form.AppField name="displayName">
          {(field) => <field.TextField label="Display name" autoComplete="name" />}
        </form.AppField>
        <form.AppField name="email">
          {(field) => <field.TextField label="Email" type="email" autoComplete="email" />}
        </form.AppField>
        <form.AppField name="language">
          {(field) => (
            <field.Field>
              <FieldLabel htmlFor={languageId}>Language</FieldLabel>
              <Select
                items={languages}
                value={field.state.value}
                onValueChange={(value) => {
                  field.handleChange(value ?? "en");
                }}
              >
                <SelectTrigger id={languageId} className="w-full" onBlur={field.handleBlur}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectGroup>
                    {languages.map((language) => (
                      <SelectItem key={language.value} value={language.value}>
                        {language.label}
                      </SelectItem>
                    ))}
                  </SelectGroup>
                </SelectContent>
              </Select>
            </field.Field>
          )}
        </form.AppField>
        <form.AppField name="weeklyDigest">
          {(field) => (
            <field.SwitchField
              label="Weekly digest"
              description="A summary of activity every Monday."
            />
          )}
        </form.AppField>
        <form.AppField name="mentions">
          {(field) => <field.SwitchField label="Email me when I am mentioned" />}
        </form.AppField>
        <form.SubmitButton className="self-start">Save preferences</form.SubmitButton>
      </FieldGroup>
    </Form>
  );
};

/**
 * Controls are drawn as blocks at their own size and labels as bars, so the form keeps its layout.
 * The form mounts with the loaded values, so there is no empty form to flash first.
 */
export const defaultProps = {} satisfies { latency?: number };

export default function SkeletonFormExample({ latency }: { latency?: number } = defaultProps) {
  const request = useSimulatedFetch(preferences, { latency });

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <Skeleton
        data={request.data}
        sample={samplePreferences}
        loading={request.loading}
        id="skeleton-preferences"
        label="Loading preferences"
        className="w-full"
      >
        {(value) => <PreferencesForm initial={value} />}
      </Skeleton>
    </div>
  );
}

import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { useSimulatedFetch } from "../../loading";
import { profile, sampleProfile } from "../fixtures";
import { ProfileCard } from "./skeleton-demo";

/**
 * Pass `loading` with the data still on screen. The skeleton is drawn from that data, so it matches
 * exactly, and the new data crossfades in. Refetches that answer within 150 ms show no skeleton.
 */
export const defaultProps = {} satisfies { latency?: number };

export default function SkeletonRefetchExample({ latency }: { latency?: number } = defaultProps) {
  const request = useSimulatedFetch(profile, { latency });

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <Skeleton
        data={request.data}
        sample={sampleProfile}
        loading={request.loading}
        label="Refreshing profile"
        className="w-full"
      >
        {(value) => <ProfileCard profile={value} />}
      </Skeleton>
    </div>
  );
}

import { Fragment, useId, useState } from "react";
import type { ReactNode } from "react";
import { Badge } from "@/registry/erbium/ui/badge";
import { Button } from "@/registry/erbium/ui/button";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Icon } from "@/registry/erbium/ui/icon";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemSeparator,
  ItemTitle,
} from "@/registry/erbium/ui/item";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/registry/erbium/ui/select";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { Switch } from "@/registry/erbium/ui/switch";
import { useSimulatedFetch } from "../../loading";
import { sampleSessions, sampleSettings, sessions, settings } from "../fixtures";
import type { Session, Settings } from "../fixtures";

const timezones = [
  { label: "Berlin (GMT+1)", value: "Europe/Berlin" },
  { label: "Lisbon (GMT)", value: "Europe/Lisbon" },
  { label: "New York (GMT−5)", value: "America/New_York" },
  { label: "Tokyo (GMT+9)", value: "Asia/Tokyo" },
];

const PreferenceRows = ({ value }: { value: Settings }) => (
  <ItemGroup variant="panel">
    <Item>
      <ItemContent>
        <ItemTitle>Time zone</ItemTitle>
        <ItemDescription>Used for dates and reminders</ItemDescription>
      </ItemContent>
      <ItemActions>
        <Select items={timezones} defaultValue={value.timezone}>
          <SelectTrigger size="sm" aria-label="Time zone">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {timezones.map((timezone) => (
              <SelectItem key={timezone.value} value={timezone.value}>
                {timezone.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </ItemActions>
    </Item>
    <ItemSeparator />
    <Item render={<Field orientation="horizontal" />}>
      <ItemContent>
        <ItemTitle>
          <FieldLabel>Security alerts</FieldLabel>
        </ItemTitle>
        <ItemDescription>Email me when someone signs in from a new device</ItemDescription>
      </ItemContent>
      <ItemActions>
        <Switch defaultChecked={value.securityAlerts} />
      </ItemActions>
    </Item>
    <ItemSeparator />
    <Item render={<Field orientation="horizontal" />}>
      <ItemContent>
        <ItemTitle>
          <FieldLabel>Product updates</FieldLabel>
        </ItemTitle>
        <ItemDescription>A short note when we ship something new</ItemDescription>
      </ItemContent>
      <ItemActions>
        <Switch defaultChecked={value.productUpdates} />
      </ItemActions>
    </Item>
  </ItemGroup>
);

const SessionRows = ({ value }: { value: Session[] }) => (
  <ItemGroup variant="panel">
    {value.map((session, index) => (
      <Fragment key={session.id}>
        {index > 0 && <ItemSeparator />}
        <Item>
          <ItemMedia variant="icon">
            <Icon name="globe" aria-hidden="true" />
          </ItemMedia>
          <ItemContent>
            <ItemTitle>
              {session.device}
              {session.current ? <Badge variant="success">This device</Badge> : null}
            </ItemTitle>
            <ItemDescription>
              {session.location} · {session.lastActive}
            </ItemDescription>
          </ItemContent>
          {session.current ? null : (
            <ItemActions>
              <Button variant="ghost" size="sm">
                Sign out
              </Button>
            </ItemActions>
          )}
        </Item>
      </Fragment>
    ))}
  </ItemGroup>
);

const Section = ({
  title,
  description,
  children,
}: {
  title: string;
  description: string;
  children: ReactNode;
}) => {
  const headingId = useId();

  return (
    <section aria-labelledby={headingId} className="flex flex-col gap-group">
      {/* Known before any request answers, so it renders at once, outside the skeleton. */}
      <div className="flex flex-col gap-0.5 px-4">
        <h3 id={headingId} className="text-subtitle">
          {title}
        </h3>
        <p className="text-caption text-muted-foreground">{description}</p>
      </div>
      {children}
    </section>
  );
};

/**
 * A page whose sections come from separate requests. Each section wraps only its own data in its own
 * `Skeleton`, so a slow request holds back only that section and a failed one shows its error
 * while the rest of the page stays usable. Headings are known, so they stay outside the skeleton.
 */
export const defaultProps = {} satisfies { latency?: number };

export default function SkeletonSectionsExample({
  latency = 1200,
}: { latency?: number } = defaultProps) {
  const [failSessions, setFailSessions] = useState(false);
  const failId = useId();

  const settingsRequest = useSimulatedFetch(settings, { latency });

  const sessionsRequest = useSimulatedFetch(sessions, {
    fail: failSessions,
    latency: latency * 2,
  });

  return (
    <div className="flex w-full max-w-lg flex-col gap-section">
      <div className="flex flex-wrap items-center justify-center gap-group">
        <Field orientation="horizontal" className="w-auto">
          <Switch
            id={failId}
            checked={failSessions}
            onCheckedChange={(checked) => {
              setFailSessions(checked);
              sessionsRequest.reload();
            }}
          />
          <FieldLabel htmlFor={failId}>Fail the sessions request</FieldLabel>
        </Field>
        <Button
          variant="outline"
          size="sm"
          disabled={settingsRequest.loading || sessionsRequest.loading}
          onClick={() => {
            settingsRequest.reload();
            sessionsRequest.reload();
          }}
        >
          Reload page
        </Button>
      </div>
      <Section title="Preferences" description="How dates appear and when we contact you.">
        <Skeleton
          data={settingsRequest.data}
          sample={sampleSettings}
          loading={settingsRequest.loading}
          id="skeleton-sections-preferences"
          label="Loading preferences"
        >
          {(value) => <PreferenceRows value={value} />}
        </Skeleton>
      </Section>
      <Section title="Sessions" description="Devices signed in to your account.">
        <Skeleton
          data={sessionsRequest.data}
          sample={sampleSessions}
          loading={sessionsRequest.loading}
          error={sessionsRequest.error}
          id="skeleton-sections-sessions"
          label="Loading sessions"
        >
          {(value) => <SessionRows value={value} />}
        </Skeleton>
        {sessionsRequest.error === undefined ? null : (
          <Button
            variant="outline"
            size="sm"
            className="self-start"
            onClick={() => {
              sessionsRequest.reload();
            }}
          >
            Try again
          </Button>
        )}
      </Section>
    </div>
  );
}

import { useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/registry/erbium/ui/empty";
import { Skeleton } from "@/registry/erbium/ui/skeleton";
import { ToggleGroup, ToggleGroupItem } from "@/registry/erbium/ui/toggle-group";
import { useSimulatedFetch } from "../../loading";
import { members, sampleMembers } from "../fixtures";
import type { Member } from "../fixtures";
import { SkeletonMemberList } from "./skeleton-avatar";

// Stable, so the request only restarts when the outcome changes.
const noMembers: Member[] = [];

type Outcome = "rows" | "empty" | "error";

/**
 * One region, every state. An `Error` renders Erbium's error alert with its message; `empty` shows
 * `emptyMessage`. Each replaces the skeleton with the same crossfade as content.
 */
export const defaultProps = {} satisfies { latency?: number };

export default function SkeletonStatesExample({ latency }: { latency?: number } = defaultProps) {
  const [outcome, setOutcome] = useState<Outcome>("rows");

  const request = useSimulatedFetch(outcome === "empty" ? noMembers : members, {
    fail: outcome === "error",
    latency,
  });

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <ToggleGroup
        aria-label="Response"
        value={[outcome]}
        onValueChange={(value) => {
          const [next] = value;

          if (next === "rows" || next === "empty" || next === "error") {
            setOutcome(next);
            request.reload();
          }
        }}
      >
        <ToggleGroupItem value="rows">Rows</ToggleGroupItem>
        <ToggleGroupItem value="empty">Empty</ToggleGroupItem>
        <ToggleGroupItem value="error">Error</ToggleGroupItem>
      </ToggleGroup>
      <Skeleton
        data={request.data}
        sample={sampleMembers}
        loading={request.loading}
        error={request.error}
        empty={request.data?.length === 0}
        emptyMessage={
          <Empty>
            <EmptyHeader>
              <EmptyTitle>No members yet</EmptyTitle>
              <EmptyDescription>Invite someone to start collaborating.</EmptyDescription>
            </EmptyHeader>
          </Empty>
        }
        label="Loading members"
        className="w-full"
      >
        {(value) => <SkeletonMemberList members={value} />}
      </Skeleton>
      <Button
        variant="outline"
        size="sm"
        onClick={() => {
          request.reload();
        }}
        disabled={request.loading}
      >
        Try again
      </Button>
    </div>
  );
}

import { use, useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import { SkeletonSuspense } from "@/registry/erbium/ui/skeleton";
import { defaultLatency } from "../../loading";
import { profile, sampleProfile } from "../fixtures";
import type { Profile } from "../fixtures";
import { ProfileCard } from "./skeleton-demo";

const wait = async (ms: number) => {
  // Browsers have no promise-based timer, so the delay wraps `setTimeout`.
  // oxlint-disable-next-line promise/avoid-new
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
};

const fetchProfile = async (latency: number): Promise<Profile> => {
  await wait(latency);

  return profile;
};

const LoadedProfile = ({ request }: { request: Promise<Profile> }) => (
  <ProfileCard profile={use(request)} />
);

/**
 * A Suspense boundary whose fallback is the component rendered from sample data, measured into a
 * skeleton. Use it where the data comes from `use(promise)` or a suspending query.
 */
export const defaultProps = {} satisfies {
  latency?: number;
};

export default function SkeletonSuspenseExample({
  latency = defaultLatency,
}: {
  latency?: number;
} = defaultProps) {
  const [suspended, setSuspended] = useState(() => ({
    attempt: 0,
    request: fetchProfile(latency),
  }));

  return (
    <div className="flex w-full max-w-sm flex-col items-center gap-group">
      <SkeletonSuspense
        key={suspended.attempt}
        skeleton={<ProfileCard profile={sampleProfile} />}
        label="Loading profile"
        className="w-full"
      >
